import type { bool, int64 } from "@gotots/gostdlib/internal/scalars.js";
import { RuntimeSlice } from "@gotots/runtime/slice.js";
export type BinaryLess<T> = (left: T, right: T) => bool;
export type Convert<Source, Target> = (value: Source) => Target;
export type CopyValue<T> = (value: T) => T;
export type EqualValue<Left, Right = Left> = (left: Left, right: Right) => bool;
export type FromContainerStorage<T, Storage> = (value: Storage) => T;
export type ToContainerStorage<T, Storage> = (value: T) => Storage;
export type Zero<T> = () => T;
export declare function readElement<T, Storage>(source: RuntimeSlice<Storage>, index: number, copy: CopyValue<T>, fromStorage: FromContainerStorage<T, Storage>): T;
export declare function storeElement<T, Storage>(target: RuntimeSlice<Storage>, index: number, value: T, copy: CopyValue<T>, toStorage: ToContainerStorage<T, Storage>): void;
export declare function storedValues<T, Storage>(source: RuntimeSlice<Storage>, copy: CopyValue<T>, fromStorage: FromContainerStorage<T, Storage>, toStorage: ToContainerStorage<T, Storage>): Storage[];
export declare function orderedCompare<T>(less: BinaryLess<T>, equal: EqualValue<T>, left: T, right: T): int64;
export declare function compareLengths(left: number, right: number): int64;
